import React, { useState } from "react";
import axios from "../utils/axios";

const AddExpenseForm = ({ budgetId, onExpenseAdded }) => {
  const [description, setDescription] = useState("");
  const [amount, setAmount] = useState("");
  const [date, setDate] = useState(() => new Date().toISOString().split("T")[0]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(""); setSuccess(false);
    setLoading(true);
    try {
      await axios.post(`/api/budgets/${budgetId}/expenses`,
        { description, amount: parseFloat(amount), date },
        { headers: { email: localStorage.getItem("email") } }
      );
      setDescription(""); setAmount(""); setDate(new Date().toISOString().split("T")[0]);
      setSuccess(true);
      setTimeout(() => setSuccess(false), 2000);
      onExpenseAdded();
    } catch (err) {
      setError("Failed to add expense");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ background: "#fafaf9", border: "1px solid #e8e8e6", borderRadius: 10, padding: 24, fontFamily: "'Inter', sans-serif" }}>
      <div style={{ fontSize: 15, fontWeight: 600, color: "#191919", marginBottom: 20 }}>Add Expense</div>

      {error && <div style={{ background: "#fff0f0", border: "1px solid #fecaca", color: "#dc2626", borderRadius: 8, padding: "10px 14px", fontSize: 13, marginBottom: 16 }}>{error}</div>}
      {success && <div style={{ background: "#f0fdf4", border: "1px solid #bbf7d0", color: "#15803d", borderRadius: 8, padding: "10px 14px", fontSize: 13, marginBottom: 16 }}>✓ Expense added!</div>}

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: 14 }}>
        {[
          { label: "Description", type: "text", val: description, set: setDescription, ph: "e.g. McDonald's" },
          { label: "Amount (RM)", type: "number", val: amount, set: setAmount, ph: "25.00", extra: { min: "0.01", step: "0.01" } },
          { label: "Date", type: "date", val: date, set: setDate, ph: "" },
        ].map(({ label, type, val, set, ph, extra }) => (
          <div key={label}>
            <label style={{ display: "block", fontSize: 13, fontWeight: 500, color: "#374151", marginBottom: 6 }}>{label}</label>
            <input type={type} value={val} required placeholder={ph} onChange={e => set(e.target.value)} {...(extra || {})}
              style={{ width: "100%", padding: "9px 12px", border: "1px solid #e8e8e6", borderRadius: 8, fontSize: 14, color: "#191919", background: "#fff", outline: "none", fontFamily: "'Inter', sans-serif", boxSizing: "border-box", transition: "border-color 0.15s" }}
              onFocus={e => e.target.style.borderColor = "#2563eb"}
              onBlur={e => e.target.style.borderColor = "#e8e8e6"} />
          </div>
        ))}

        <button type="submit" disabled={loading} style={{ padding: "10px", background: "#2563eb", color: "#fff", border: "none", borderRadius: 8, fontSize: 14, fontWeight: 500, cursor: "pointer", fontFamily: "'Inter', sans-serif", marginTop: 4, opacity: loading ? 0.7 : 1 }}>
          {loading ? "Adding…" : "Add Expense"}
        </button>
      </form>
    </div>
  );
};

export default AddExpenseForm;
